using StackExchange.Redis;

var mux = ConnectionMultiplexer.Connect("localhost:6379");
var db = mux.GetDatabase();

// Store session fields as a hash instead of a JSON string
string sessionKey = $"session:{sessionId}";

await db.HashSetAsync(sessionKey, new HashEntry[]
{
    new HashEntry("userId", userId),
    new HashEntry("username", username),
    new HashEntry("role", role),
    new HashEntry("created", DateTime.UtcNow.ToBinary())
});

// Set TTL for automatic expiration
await db.KeyExpireAsync(sessionKey, TimeSpan.FromHours(1));

// Fetch only the fields you need
string username = await db.HashGetAsync(sessionKey, "username");

const Redis = require('ioredis');
const redis = new Redis();

async function tagArticle(articleId, tag) {
  // Use a set for unique tags per article
  const key = `article:${articleId}:tags`;
  await redis.sadd(key, tag);
  await redis.expire(key, 86400); // 1 day
}

async function getArticleTags(articleId) {
  // SMEMBERS returns unique tags without duplicates
  return await redis.smembers(`article:${articleId}:tags`);
}

